// ESP32 Microcontroller Edge Firmware (C++ / FreeRTOS)
#include <WiFi.h>
#include <HTTPClient.h>
#include <ArduinoJson.h>

#define VIBRATION_PIN 34
#define ALERT_LED_PIN 2

void setup() {
  Serial.begin(115200);
  pinMode(ALERT_LED_PIN, OUTPUT);
  WiFi.begin(SSID, PASSWORD);
  while (WiFi.status() != WL_CONNECTED) delay(500);
}

void loop() {
  float vibration = analogRead(VIBRATION_PIN) * (3.3 / 4095.0);
  StaticJsonDocument<200> doc;
  doc["sensor_id"] = "edge-node-01";
  doc["vibration_g"] = vibration;
  doc["timestamp_ms"] = millis();

  String payload;
  serializeJson(doc, payload);
  HTTPClient http;
  http.begin("http://aiops-telemetry-server:8000/api/v1/stream");
  http.addHeader("Content-Type", "application/json");
  int code = http.POST(payload);
  http.end();
  delay(100);
}
